/**
 * Documentation classification gate (ADR-0042 / DOCS_SYSTEM_DESIGN.md E4).
 *
 * The documentation universe is audited by `rules/docs-taxonomy.yaml` (artifact
 * types + impact edges). This gate is its file-level complement: it forces
 * **conscious classification of every tracked markdown document** so none can
 * rot silently between the fact markers and the taxonomy.
 *
 * It auto-classifies each tracked `*.md` by content/path:
 *   generated        `<!-- GENERATED by -->` marker or a known generator output
 *   fact-markered    contains `usa:fact` / `usa:begin` markers
 *   immutable-history `docs/adr/*.md` (ADR-hygiene gates these)
 *   meta             `docs/writing-docs.md`
 *   changeset-note   `.changeset/*.md` (machine-managed)
 *   machine-written  `CHANGELOG.md` (machine-managed)
 *
 * Everything else MUST appear under `standalone:` in `docs/manifest.yaml` with
 * a `reviewed: YYYY-MM-DD` date and a `reason`. A review older than
 * `review_period_days` fails the build, so prose truth is re-validated on a
 * schedule the team owns.
 *
 * Exit 1 on any violation (unclassified doc, expired review, malformed
 * manifest, or a manifest entry pointing at an auto-classified doc). Exit 0
 * clean. Usage: `node scripts/check-manifest.mjs`.
 */
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { parse as parseYaml } from 'yaml';

const ROOT = process.cwd();
const MANIFEST = path.join(ROOT, 'docs', 'manifest.yaml');

const GENERATED_BY_PATH = new Set([
  'docs/reference/cli.md',
  'docs/reference/asvs-coverage.md',
  'examples/sample-report.md',
]);

function excluded(f) {
  return f.startsWith('experiments/') || f.startsWith('examples/demo-app/') || f === 'CHANGELOG.md';
}

function trackedMarkdown() {
  return execFileSync('git', ['ls-files', '*.md'], { encoding: 'utf8', cwd: ROOT })
    .trim()
    .split('\n')
    .filter((f) => f && !excluded(f));
}

function classify(rel, text) {
  if (rel.startsWith('docs/adr/')) return 'immutable-history';
  if (rel === 'docs/writing-docs.md') return 'meta';
  if (rel.startsWith('.changeset/')) return 'changeset-note';
  if (rel === 'CHANGELOG.md') return 'machine-written';
  if (GENERATED_BY_PATH.has(rel)) return 'generated';
  if (text.includes('<!-- GENERATED by')) return 'generated';
  if (text.includes('usa:fact') || text.includes('usa:begin')) return 'fact-markered';
  return 'standalone';
}

const failures = [];
const fail = (m) => failures.push(m);

const manifestSrc = fs.readFileSync(MANIFEST, 'utf8');
let manifest;
try {
  manifest = parseYaml(manifestSrc);
} catch (err) {
  console.error(`manifest: docs/manifest.yaml is not valid YAML: ${err.message ?? err}`);
  process.exit(1);
}

if (manifest.schema !== 'usa-doc-manifest-v1') {
  fail(`manifest: schema must be 'usa-doc-manifest-v1' (got '${manifest.schema ?? '(none)'}')`);
}
const period = Number(manifest.review_period_days);
if (!Number.isInteger(period) || period <= 0) {
  fail(
    `manifest: review_period_days must be a positive integer (got ${manifest.review_period_days})`,
  );
}

const today = new Date();
const declared = new Map();
const standalone = manifest.standalone ?? [];
for (const e of standalone) {
  if (!e.file) {
    fail('manifest: a standalone entry is missing its `file:` field');
    continue;
  }
  if (declared.has(e.file)) {
    fail(`manifest: duplicate standalone entry for ${e.file}`);
    continue;
  }
  if (!e.reviewed) {
    fail(`manifest: ${e.file} is missing a 'reviewed' date`);
    continue;
  }
  if (!e.reason) {
    fail(`manifest: ${e.file} is missing a 'reason'`);
    continue;
  }
  const reviewed = new Date(e.reviewed);
  if (Number.isNaN(reviewed.getTime())) {
    fail(`manifest: ${e.file} has an unparseable 'reviewed' date: ${e.reviewed}`);
    continue;
  }
  const ageDays = (today.getTime() - reviewed.getTime()) / 86_400_000;
  const maxAge = Number.isFinite(period) ? period : 180;
  if (ageDays > maxAge) {
    fail(
      `manifest: ${e.file} last reviewed ${e.reviewed} — older than the ${maxAge}-day review window. Re-verify the doc and bump 'reviewed'.`,
    );
  }
  declared.set(e.file, true);
}

const files = new Set(trackedMarkdown());
const unclassified = [];
for (const rel of files) {
  const text = fs.existsSync(path.join(ROOT, rel))
    ? fs.readFileSync(path.join(ROOT, rel), 'utf8')
    : '';
  const cat = classify(rel, text);
  if (cat === 'standalone') {
    if (!declared.has(rel)) {
      unclassified.push(rel);
    }
  } else {
    // auto-classified docs must NOT be hand-listed as standalone
    if (declared.has(rel)) {
      fail(
        `manifest: ${rel} is auto-classified as '${cat}' but is also listed under standalone — remove it from the manifest.`,
      );
    }
  }
}
for (const rel of unclassified) {
  fail(
    `manifest: tracked doc ${rel} has no classification — add a standalone entry to docs/manifest.yaml, or convert it to a marked/generated doc so it is auto-classified.`,
  );
}

// manifest entries for files that are not tracked markdown (stale pointers)
for (const rel of declared.keys()) {
  if (!files.has(rel)) {
    fail(
      `manifest: ${rel} is listed as standalone but is not a tracked markdown file (stale pointer).`,
    );
  }
}

if (failures.length > 0) {
  console.error(`doc manifest: ${failures.length} problem(s):\n- ${failures.join('\n- ')}`);
  process.exit(1);
}
console.log(
  `doc manifest: OK (${files.size} tracked docs · ${standalone.length} standalone · ${period}-day review window)`,
);
